/** Sprints, session templates, the exercise picker, and one-day changes that leave the sprint plan as it is. */
final class WorkoutPlan {
    final WorkoutScreen screen;final MainActivity a;final AppUi ui;
    static final String[] PHASES={"Reconditioning","Hypertrophy","Strength","Aerobic base","Running","Alpine hiking","Lean bulk","Maintenance","Deload"};
    WorkoutPlan(WorkoutScreen s){screen=s;a=s.a;ui=s.ui;}

    /** Coach-led cycles: the coach plans and names a sprint from your discussion; manual setup stays available as a second path. */
    void open(){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Sprints");List<JSONObject> sprints=WorkoutStore.rows(a,"sprint");Collections.sort(sprints,(x,y)->y.optJSONObject("data").optString("start").compareTo(x.optJSONObject("data").optString("start")));JSONObject now=WorkoutStore.sprint(a);if(now!=null)s.body.addView(sprintCard(now,s),WorkoutViews.gap(ui,12));AppUi.Pill ask=ui.primaryButton(now==null?"Set up a sprint with your coach":"Plan the next sprint with your coach",()->{s.dialog.dismiss();try{screen.coach.open(new JSONObject().put("purpose","plan_sprint"),null,"Plan my next sprint from my progress and goals, and name it.");}catch(JSONException ignored){}});s.body.addView(ask,WorkoutViews.gap(ui,8));s.body.addView(ui.ghostButton("Set up manually",()->{s.dialog.dismiss();edit(null);}),WorkoutViews.gap(ui,14));boolean first=true;for(JSONObject r:sprints){if(now!=null&&r.optString("id").equals(now.optString("id")))continue;if(first){s.body.addView(ui.label("Past and planned"),WorkoutViews.gap(ui,6));first=false;}JSONObject d=r.optJSONObject("data");s.body.addView(WorkoutViews.row(ui,d.optString("name"),d.optString("phase")+" · "+d.optString("start")+" to "+d.optString("end"),()->sprint(r.optString("id"))),WorkoutViews.gap(ui,8));}s.show();}
    private JSONObject evidence(String id){JSONArray all=screen.overview().optJSONArray("sprints");for(int i=0;all!=null&&i<all.length();i++)if(id.equals(all.optJSONObject(i).optString("id")))return all.optJSONObject(i);return null;}
    private View sprintCard(JSONObject row,WorkoutViews.Sheet parent){String id=row.optString("id");JSONObject d=row.optJSONObject("data"),ev=evidence(id);int done=ev==null?0:ev.optInt("completed"),target=d.optInt("target_sessions");LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type(d.optString("name"),18,24,700,0,ui.text));c.addView(ui.type(d.optString("phase")+" · until "+LocalDate.parse(d.optString("end")).format(WorkoutScreen.SHORT),12.5f,17,400,0,ui.muted),WorkoutViews.gap(ui,10));if(target>0){LinearLayout t=ui.row();t.addView(ui.type(done+" of "+target+" workouts",14,20,600,0,ui.text),new LinearLayout.LayoutParams(0,-2,1));c.addView(t);FrameLayout track=new FrameLayout(a);track.setBackground(ui.outline(ui.stroke,4,0,0));track.setClipToOutline(true);View fill=new View(a);fill.setBackground(ui.aurora(0,false));fill.setPivotX(0);fill.setScaleX(Math.min(1f,done/(float)target));track.addView(fill,new FrameLayout.LayoutParams(-1,-1));c.addView(track,MainParts.params(ui,-1,ui.dp(8),0,6,0,10));}
        JSONArray cycle=d.optJSONArray("cycle");if(cycle!=null&&cycle.length()>0){c.addView(ui.type("Workout cycle",12.5f,17,600,0,ui.muted),WorkoutViews.gap(ui,4));for(int i=0;i<cycle.length();i++){String tid=cycle.optString(i);JSONObject t=WorkoutStore.data(a,"template",tid);if(t!=null)c.addView(WorkoutViews.row(ui,(i+1)+" · "+t.optString("name"),screen.summary(t),()->template(tid)),WorkoutViews.gap(ui,6));}}
        boolean late=target>0&&done<target&&!LocalDate.parse(d.optString("end")).isAfter(LocalDate.now().plusDays(14));if(late){c.addView(ui.type("There's still "+(target-done)+(target-done==1?" workout":" workouts")+" to go. Extending just gives you more time.",13,18,400,0,ui.muted),WorkoutViews.gap(ui,6));c.addView(ui.quietButton("Extend by a month",()->{String end=LocalDate.parse(d.optString("end")).plusMonths(1).toString();int revision=row.optInt("revision");String mutation=WorkoutStore.id();new Thread(()->{String problem=null;try{Cloud.call(a,"workout/sprints/"+id+"/extend",new JSONObject().put("end",end).put("base_revision",revision).put("mutation_id",mutation),true);}catch(Exception e){problem="You need a connection to extend the sprint.";}String m=problem;a.runOnUiThread(()->{if(m!=null){Toast.makeText(a,m,Toast.LENGTH_LONG).show();return;}parent.dialog.dismiss();screen.refresh();});}).start();}),WorkoutViews.gap(ui,6));}
        LinearLayout more=ui.row();more.addView(ui.ghostButton("Details",()->sprint(id)),new LinearLayout.LayoutParams(0,-2,1));more.addView(ui.ghostButton("Edit",()->{parent.dialog.dismiss();edit(id);}),new LinearLayout.LayoutParams(0,-2,1));c.addView(more);return c;}
    /** Each template is a card with its exercises drawn out, ready to start. */
    void templates(){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Templates");for(JSONObject r:templateRows()){JSONObject d=r.optJSONObject("data");String id=r.optString("id");LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type(d.optString("name"),16,22,700,0,ui.text));String sum=screen.summary(d);if(!sum.isEmpty())c.addView(ui.type(sum,12.5f,17,400,0,ui.muted));LinearLayout art=ui.row();JSONArray ex=d.optJSONArray("exercises");for(int i=0;ex!=null&&i<Math.min(5,ex.length());i++)art.addView(WorkoutArt.tile(ui,ex.optJSONObject(i).optString("exercise_id"),44),MainParts.params(ui,ui.dp(44),ui.dp(44),0,0,6,0));c.addView(art,MainParts.params(ui,-1,-2,0,10,0,10));LinearLayout b=ui.row();Button go=ui.quietButton("Start workout",()->{s.dialog.dismiss();screen.begin(d.optString("name"),id,null,null,null);});go.setTag("template_start");b.addView(go,MainParts.weighted(ui,1,0,0,6,0));b.addView(ui.ghostButton("Edit",()->{s.dialog.dismiss();template(id);}),new LinearLayout.LayoutParams(-2,-2));c.addView(b);s.body.addView(c,WorkoutViews.gap(ui,10));}if(templateRows().isEmpty())s.body.addView(ui.detail("No templates yet."),WorkoutViews.gap(ui,8));s.body.addView(ui.ghostButton("New template",()->{s.dialog.dismiss();template(null);}));s.show();}
    List<JSONObject> templateRows(){List<JSONObject> t=WorkoutStore.rows(a,"template");Collections.sort(t,(x,y)->x.optJSONObject("data").optString("name").compareTo(y.optJSONObject("data").optString("name")));return t;}
    /** Evidence, the coach's reading and the proposal stay separate; applying a next sprint happens in Coach, with approval. */
    void sprint(String id){JSONObject d=WorkoutStore.data(a,"sprint",id);if(d==null)return;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,d.optString("name"));s.body.addView(ui.detail(d.optString("phase")+" · "+d.optString("start")+" to "+d.optString("end")),WorkoutViews.gap(ui,10));JSONObject ev=null;JSONArray all=screen.overview().optJSONArray("sprints");for(int i=0;all!=null&&i<all.length();i++)if(id.equals(all.optJSONObject(i).optString("id")))ev=all.optJSONObject(i);boolean cyclic=d.optJSONArray("cycle")!=null&&d.optJSONArray("cycle").length()>0;if(cyclic){try{ev=ev==null?new JSONObject():new JSONObject(ev.toString());ev.put("completed",WorkoutStore.sprintCompleted(a,id)).put("planned",d.optInt("target_sessions"));}catch(JSONException ignored){}}LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type("Evidence",15,20,700,0,ui.text));if(ev==null)c.addView(ui.type("Appears after your next sync.",13,18,400,0,ui.muted));else{c.addView(WorkoutViews.pair(ui,"Sessions",ev.optInt("completed")+" of "+ev.optInt("planned"),ui.text));if(ev.optInt("recovery_adjusted_skips")>0)c.addView(WorkoutViews.pair(ui,"Recovery skips, not counted",""+ev.optInt("recovery_adjusted_skips"),ui.text));if(!ev.isNull("average_duration_seconds")&&ev.has("average_duration_seconds"))c.addView(WorkoutViews.pair(ui,"Average session",WorkoutViews.clock(ev.optLong("average_duration_seconds")),ui.text));}s.body.addView(c,WorkoutViews.gap(ui,10));
        JSONArray goals=d.optJSONArray("success_criteria");if(goals!=null&&goals.length()>0){LinearLayout g=WorkoutViews.card(ui);g.addView(ui.type("Success criteria",15,20,700,0,ui.text));for(int i=0;i<goals.length();i++)g.addView(ui.type(goals.optString(i),13.5f,19,400,0,ui.text));s.body.addView(g,WorkoutViews.gap(ui,10));}
        JSONArray plan=d.optJSONArray("cycle");if(plan!=null&&plan.length()>0){LinearLayout p=WorkoutViews.card(ui);p.addView(ui.type("Workout cycle",15,20,700,0,ui.text));for(int i=0;i<plan.length();i++){JSONObject t=WorkoutStore.data(a,"template",plan.optString(i));p.addView(WorkoutViews.pair(ui,String.valueOf(i+1),t==null?"Session":t.optString("name"),ui.muted));}s.body.addView(p,WorkoutViews.gap(ui,10));}
        if(!d.optString("retrospective").isEmpty()){LinearLayout r=WorkoutViews.card(ui);r.addView(ui.type("Review",15,20,700,0,ui.text));r.addView(ui.type(d.optString("retrospective"),13.5f,19,400,0,ui.text));s.body.addView(r,WorkoutViews.gap(ui,10));}
        s.body.addView(ui.quietButton("Ask coach to review this sprint",()->{try{screen.coach.open(new JSONObject().put("purpose","sprint_review").put("sprint_id",id),null,"Review "+d.optString("name")+": evidence, your reading, and a proposed next sprint for my approval.");}catch(JSONException ignored){}}),WorkoutViews.gap(ui,8));s.body.addView(ui.quietButton("Edit sprint",()->{s.dialog.dismiss();edit(id);}),WorkoutViews.gap(ui,8));if("active".equals(d.optString("status")))s.body.addView(ui.ghostButton("Mark complete",()->{try{d.put("status","completed");WorkoutStore.put(a,"sprint",id,d);s.dialog.dismiss();screen.refresh();}catch(JSONException ignored){}}));s.show();}

    /** Manual setup: focus, dates and the ordered workouts that repeat until the target is reached. Four calendar months by default. */
    void edit(String id){JSONObject found=id==null?null:WorkoutStore.data(a,"sprint",id);JSONObject base;try{base=found==null?new JSONObject().put("status","active"):new JSONObject(found.toString());}catch(JSONException e){return;}final JSONObject d=base;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,id==null?"Set up a sprint":"Edit sprint");EditText name=ui.field("Name",d.optString("name",""));s.body.addView(name,WorkoutViews.gap(ui,8));final String[] phase={d.optString("phase",PHASES[0])};Button pick=ui.quietButton("Focus: "+phase[0],null);pick.setOnClickListener(v->new AlertDialog.Builder(a).setItems(PHASES,(x,i)->{phase[0]=PHASES[i];pick.setText("Focus: "+phase[0]);}).show());s.body.addView(pick,WorkoutViews.gap(ui,8));LocalDate today=LocalDate.now();EditText start=ui.field("Start, YYYY-MM-DD",d.optString("start",today.toString())),end=ui.field("End, YYYY-MM-DD",d.optString("end",today.plusMonths(4).toString())),target=ui.field("Target workouts",d.has("target_sessions")?""+d.optInt("target_sessions"):"48");target.setInputType(InputType.TYPE_CLASS_NUMBER);s.body.addView(start,WorkoutViews.gap(ui,8));s.body.addView(end,WorkoutViews.gap(ui,8));s.body.addView(target,WorkoutViews.gap(ui,8));EditText goals=ui.field("Success criteria, one per line",join(d.optJSONArray("success_criteria")));goals.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);goals.setSingleLine(false);goals.setMinLines(2);s.body.addView(goals,WorkoutViews.gap(ui,12));
        s.body.addView(ui.label("Workout cycle"),WorkoutViews.gap(ui,6));ArrayList<String> cycle=new ArrayList<>();JSONArray old=d.optJSONArray("cycle");for(int i=0;old!=null&&i<old.length();i++)cycle.add(old.optString(i));LinearLayout rows=ui.column();s.body.addView(rows);Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();for(int i=0;i<cycle.size();i++){final int at=i;JSONObject t=WorkoutStore.data(a,"template",cycle.get(i));rows.addView(WorkoutViews.row(ui,(i+1)+" · "+(t==null?"Removed template":t.optString("name")),"Tap to remove",()->{cycle.remove(at);paint[0].run();}),WorkoutViews.gap(ui,6));}};paint[0].run();List<JSONObject> t=templateRows();s.body.addView(ui.quietButton("Add a workout to the cycle",()->{String[] names=new String[t.size()];for(int i=0;i<names.length;i++)names[i]=t.get(i).optJSONObject("data").optString("name");new AlertDialog.Builder(a).setItems(names,(x,i)->{cycle.add(t.get(i).optString("id"));paint[0].run();}).show();}),WorkoutViews.gap(ui,12));
        s.body.addView(ui.primaryButton("Save sprint",()->{try{LocalDate first=LocalDate.parse(start.getText().toString().trim()),last=LocalDate.parse(end.getText().toString().trim());if(last.isBefore(first))throw new IllegalArgumentException();int goal=Integer.parseInt(target.getText().toString().trim());JSONArray criteria=new JSONArray();for(String line:goals.getText().toString().split("\n"))if(!line.trim().isEmpty())criteria.put(line.trim());JSONArray order=new JSONArray();for(String c:cycle)order.put(c);String title=name.getText().toString().trim();if(title.isEmpty())throw new IllegalArgumentException();d.put("name",title).put("phase",phase[0]).put("start",first.toString()).put("end",last.toString()).put("cycle",order).put("target_sessions",goal).put("success_criteria",criteria);WorkoutStore.put(a,"sprint",id==null?WorkoutStore.id():id,d);s.dialog.dismiss();screen.refresh();}catch(Exception e){Toast.makeText(a,"Check the name, dates and target",Toast.LENGTH_LONG).show();}}));s.show();}
    private static String join(JSONArray v){StringBuilder b=new StringBuilder();for(int i=0;v!=null&&i<v.length();i++)b.append(i==0?"":"\n").append(v.optString(i));return b.toString();}

    void template(String id){JSONObject found=id==null?null:WorkoutStore.data(a,"template",id);JSONObject d;try{d=found==null?new JSONObject().put("exercises",new JSONArray()):new JSONObject(found.toString());}catch(JSONException e){return;}WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,id==null?"New template":"Edit template");EditText name=ui.field("Name",d.optString("name"));s.body.addView(name,WorkoutViews.gap(ui,10));LinearLayout rows=ui.column();s.body.addView(rows);Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();JSONArray ex=d.optJSONArray("exercises");for(int i=0;i<ex.length();i++){final int index=i;JSONObject p=ex.optJSONObject(i);String detail=!p.isNull("distance_m")&&p.has("distance_m")?WorkoutUnits.distance(a,p.optDouble("distance_m"))+(p.has("speed_kmh")&&!p.isNull("speed_kmh")?" at "+WorkoutUnits.speed(a,p.optDouble("speed_kmh")):""):p.optInt("sets",1)+" × "+p.optInt("min_reps")+"–"+p.optInt("max_reps")+(p.has("weight_kg")&&!p.isNull("weight_kg")?" · "+WorkoutUnits.load(a,p.optDouble("weight_kg")):"")+(p.has("rir")&&!p.isNull("rir")?" · "+WorkoutViews.kg(p.optDouble("rir"))+" RIR":"");rows.addView(WorkoutViews.row(ui,WorkoutStore.exerciseName(a,p.optString("exercise_id")),detail,()->prescription(ex,index,paint[0])),WorkoutViews.gap(ui,8));}};paint[0].run();
        s.body.addView(ui.quietButton("Add exercise",()->pick(screen,e->{try{JSONObject p=new JSONObject().put("exercise_id",e).put("sets",1).put("min_reps",8).put("max_reps",12).put("rest_seconds",120);d.getJSONArray("exercises").put(p);prescription(d.getJSONArray("exercises"),d.getJSONArray("exercises").length()-1,paint[0]);paint[0].run();}catch(JSONException ignored){}})),WorkoutViews.gap(ui,8));
        s.body.addView(ui.primaryButton("Save template",()->{String title=name.getText().toString().trim();if(title.isEmpty()){name.setError("Enter a name");return;}try{d.put("name",title);WorkoutStore.put(a,"template",id==null?WorkoutStore.id():id,d);s.dialog.dismiss();screen.refresh();}catch(JSONException ignored){}}),WorkoutViews.gap(ui,8));if(id!=null)s.body.addView(ui.quietButton("Start workout",()->{s.dialog.dismiss();screen.begin(d.optString("name"),id,null,null,null);}),WorkoutViews.gap(ui,8));if(id!=null)s.body.addView(ui.ghostButton("Delete template",()->{WorkoutStore.delete(a,"template",id);s.dialog.dismiss();screen.refresh();}));s.show();}
    private void prescription(JSONArray list,int index,Runnable after){JSONObject p=list.optJSONObject(index);boolean run=WorkoutStore.cardio(a,p.optString("exercise_id"));LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),0);String[][] fields=run?new String[][]{{"distance_m","Distance in "+WorkoutUnits.distanceLabel(a)},{"speed_kmh","Speed in "+(WorkoutUnits.imperial(a)?"mph":"km/h")}}:new String[][]{{"sets","Sets"},{"min_reps","Reps from"},{"max_reps","Reps to"},{"weight_kg","Target "+WorkoutUnits.loadLabel(a)},{"rir","Reps in reserve"},{"rest_seconds","Rest in seconds"}};EditText[] inputs=new EditText[fields.length];for(int i=0;i<fields.length;i++){String field=fields[i][0];double value=p.optDouble(field,0);inputs[i]=ui.field(fields[i][1],!p.has(field)||p.isNull(field)?"":field.equals("weight_kg")?WorkoutUnits.loadNumber(a,value):field.equals("distance_m")?WorkoutUnits.distanceNumber(a,value):field.equals("speed_kmh")?WorkoutUnits.speedNumber(a,value):WorkoutViews.kg(value));inputs[i].setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(inputs[i],WorkoutViews.gap(ui,6));}ScrollView sc=new ScrollView(a);sc.addView(box);new AlertDialog.Builder(a).setTitle(WorkoutStore.exerciseName(a,p.optString("exercise_id"))).setView(sc).setPositiveButton("Save",(x,i)->{try{for(int k=0;k<fields.length;k++){String v=inputs[k].getText().toString().trim().replace(',','.');String key=fields[k][0];if(v.isEmpty())p.remove(key);else if(key.equals("sets")||key.endsWith("reps")||key.equals("rest_seconds"))p.put(key,(int)Double.parseDouble(v));else{double shown=Double.parseDouble(v);p.put(key,key.equals("weight_kg")?WorkoutUnits.loadIn(a,shown):key.equals("distance_m")?WorkoutUnits.distanceIn(a,shown):key.equals("speed_kmh")?WorkoutUnits.speedIn(a,shown):shown);}}if(p.optInt("max_reps")<p.optInt("min_reps"))p.put("max_reps",p.optInt("min_reps"));after.run();}catch(Exception e){Toast.makeText(a,"Check the numbers",Toast.LENGTH_SHORT).show();}}).setNeutralButton("Remove",(x,i)->{list.remove(index);after.run();}).setNegativeButton("Cancel",null).show();}
    /** After a session that differed: the template takes this session's exercises and set counts. Prescribed loads are kept. */
    void saveStructure(String id,JSONObject template,JSONArray used){new AlertDialog.Builder(a).setTitle("Update the template?").setMessage("Future sessions from this template will use today's exercises and set counts. Past sessions don't change.").setPositiveButton("Update template",(x,w)->{try{JSONObject t=new JSONObject(template.toString());JSONArray old=t.optJSONArray("exercises"),next=new JSONArray();for(int i=0;i<used.length();i++){JSONObject u=used.getJSONObject(i);JSONObject p=null;for(int k=0;old!=null&&k<old.length();k++)if(u.optString("eid").equals(old.getJSONObject(k).optString("exercise_id")))p=new JSONObject(old.getJSONObject(k).toString());if(p==null)p=new JSONObject().put("exercise_id",u.optString("eid")).put("min_reps",8).put("max_reps",12).put("rest_seconds",u.optInt("rest",120));p.put("sets",Math.max(1,u.getJSONArray("sets").length()));next.put(p);}t.put("exercises",next);WorkoutStore.put(a,"template",id,t);Toast.makeText(a,"Template updated",Toast.LENGTH_SHORT).show();}catch(JSONException ignored){}}).setNegativeButton("Keep template",null).show();}

    /** Search the catalog, or add a new exercise. */
    static void pick(WorkoutScreen screen,Consumer<String> chosen){AppUi ui=screen.ui;MainActivity a=screen.a;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Choose exercise");EditText search=ui.field("Search exercises","");search.setTag("exercise_search");s.body.addView(search,WorkoutViews.gap(ui,10));LinearLayout rows=ui.column();s.body.addView(rows);List<JSONObject> all=WorkoutStore.rows(a,"exercise");Collections.sort(all,(x,y)->x.optJSONObject("data").optString("name").compareToIgnoreCase(y.optJSONObject("data").optString("name")));final HashSet<String> open=new HashSet<>();Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);TreeMap<String,List<JSONObject>> groups=new TreeMap<>();for(JSONObject r:all){JSONObject d=r.optJSONObject("data");if(!q.isEmpty()&&!d.optString("name").toLowerCase(Locale.ROOT).contains(q))continue;String g=WorkoutArt.group(d);if(!groups.containsKey(g))groups.put(g,new ArrayList<>());groups.get(g).add(r);}for(Map.Entry<String,List<JSONObject>> g:groups.entrySet()){boolean show=!q.isEmpty()||open.contains(g.getKey());LinearLayout h=ui.row();h.setMinimumHeight(ui.dp(52));h.setPadding(ui.dp(14),0,ui.dp(10),0);h.setBackground(ui.pressable(ui.outline(ui.surface,16,ui.stroke,1),16));h.addView(ui.type(g.getKey(),15,20,700,0,ui.text),new LinearLayout.LayoutParams(0,-2,1));h.addView(ui.type(String.valueOf(g.getValue().size()),13,18,500,0,ui.muted),MainParts.params(ui,-2,-2,0,0,6,0));h.addView(MainParts.icon(ui,show?"up":"down",ui.muted),new LinearLayout.LayoutParams(ui.dp(18),ui.dp(18)));h.setOnClickListener(v->{if(!open.remove(g.getKey()))open.add(g.getKey());paint[0].run();});rows.addView(h,WorkoutViews.gap(ui,6));if(show)for(JSONObject r:g.getValue()){JSONObject d=r.optJSONObject("data");LinearLayout row=ui.row();row.setMinimumHeight(ui.dp(58));row.setPadding(ui.dp(8),ui.dp(6),ui.dp(8),ui.dp(6));row.addView(new WorkoutArt.Tile(ui,d),new LinearLayout.LayoutParams(ui.dp(44),ui.dp(44)));row.addView(ui.type(d.optString("name"),14.5f,20,500,0,ui.text),MainParts.weighted(ui,1,10,0,0,0));row.setOnClickListener(v->{s.dialog.dismiss();chosen.accept(r.optString("id"));});AppUi.press(row);rows.addView(row,WorkoutViews.gap(ui,2));}}};paint[0].run();search.addTextChangedListener(new TextWatcher(){public void afterTextChanged(Editable e){paint[0].run();}public void beforeTextChanged(CharSequence c,int x,int y,int z){}public void onTextChanged(CharSequence c,int x,int y,int z){}});
        s.body.addView(ui.quietButton("New exercise",()->{EditText name=ui.field("Exercise name",search.getText().toString().trim());Switch cardio=new Switch(a);cardio.setText("Timed distance, such as a run");LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),0);box.addView(name,WorkoutViews.gap(ui,8));box.addView(cardio);new AlertDialog.Builder(a).setTitle("New exercise").setView(box).setPositiveButton("Add",(x,i)->{String v=name.getText().toString().trim();if(v.isEmpty())return;try{String id=WorkoutStore.id();WorkoutStore.put(a,"exercise",id,new JSONObject().put("name",v).put("mode",cardio.isChecked()?"cardio":"strength"));s.dialog.dismiss();chosen.accept(id);}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}));s.show();}

    /** Today only: another sprint day, edited exercises, a shorter session, or rest. The sprint plan stays and the change goes to the review. */
    void change(JSONObject next){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Change today's workout");JSONObject sprint=next.optJSONObject("sprint");String sid=sprint==null?null:sprint.optString("id"),date=next.optString("date"),current=next.optString("template_id");JSONObject t=WorkoutStore.data(a,"template",current);String name=t==null?"Session":t.optString("name");s.body.addView(ui.label("Swap with another session"),WorkoutViews.gap(ui,6));HashSet<String> seen=new HashSet<>();JSONArray plan=sprint==null?null:sprint.optJSONObject("data").optJSONArray("cycle");for(int i=0;plan!=null&&i<plan.length();i++){String tid=plan.optString(i);if(tid.equals(current)||!seen.add(tid))continue;JSONObject other=WorkoutStore.data(a,"template",tid);if(other==null)continue;s.body.addView(WorkoutViews.row(ui,other.optString("name"),"Do this instead today",()->{s.dialog.dismiss();screen.begin(other.optString("name"),tid,sid,date,change("swap_day","Swapped "+name+" for "+other.optString("name"),date));}),WorkoutViews.gap(ui,8));}
        s.body.addView(ui.label("Or"),MainParts.params(ui,-1,-2,0,8,0,6));s.body.addView(WorkoutViews.row(ui,"Edit exercises for today","Starts the session; change anything as you go",()->{s.dialog.dismiss();screen.begin(name,current,sid,date,change("edit_exercises","Chose to edit today's exercises",date));}),WorkoutViews.gap(ui,8));s.body.addView(WorkoutViews.row(ui,"Shorter session","Keeps the first half of the exercises",()->{s.dialog.dismiss();screen.begin(name,current,sid,date,change("shorter","Shortened the session",date));JSONObject d=WorkoutStore.draft(a);if(d!=null&&screen.live!=null){JSONArray ex=d.optJSONArray("exercises");for(int i=ex.length()-1;i>=Math.max(1,(ex.length()+1)/2);i--)ex.remove(i);WorkoutStore.saveDraft(a,d);screen.live.d=d;screen.live.render();}}),WorkoutViews.gap(ui,8));s.body.addView(WorkoutViews.row(ui,"Rest today","Never counts against the sprint",()->rest(s,name,current,sid,date)),WorkoutViews.gap(ui,10));s.body.addView(ui.detail("Changes apply to today only and are noted for your sprint review."));s.show();}
    private JSONObject change(String kind,String reason,String date){try{return new JSONObject().put("id",WorkoutStore.id()).put("at",OffsetDateTime.now().withNano(0).toString()).put("kind",kind).put("reason",reason).put("original_date",date);}catch(JSONException e){throw new IllegalStateException(e);}}
    private void rest(WorkoutViews.Sheet s,String name,String template,String sprint,String date){EditText why=ui.field("Why, such as still sore","");new AlertDialog.Builder(a).setTitle("Rest today?").setView(why).setPositiveButton("Rest",(x,i)->{try{String reason=why.getText().toString().trim();JSONObject w=new JSONObject().put("name",name).put("started_at",OffsetDateTime.now().withNano(0).toString()).put("timezone",ZoneId.systemDefault().getId()).put("status","skipped").put("recovery_adjusted",true).put("skip_reason",reason.isEmpty()?"Rest day":reason).put("template_id",template).put("session_changes",new JSONArray().put(change("rest_move",reason.isEmpty()?"Rest day":reason,date))).put("source",new JSONObject().put("companion",new JSONObject().put("scheduled_date",date)));if(sprint!=null)w.put("sprint_id",sprint);WorkoutStore.put(a,"workout",WorkoutStore.id(),w);s.dialog.dismiss();screen.refresh();}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}
}
